/**
 * Patches @easyops-cn/docusaurus-search-local to fix i18n route validation bug.
 * The plugin throws when routes don't start with the locale baseUrl (e.g., /zh-Hans/).
 * This patch changes the throw to a skip (return undefined) so those routes are simply ignored.
 * 
 * Related issue: routes generated by other plugins may not be prefixed with the locale baseUrl.
 */
const fs = require('fs');
const path = require('path');

const filePath = path.join(
  __dirname,
  '..',
  'node_modules',
  '@easyops-cn',
  'docusaurus-search-local',
  'dist',
  'server',
  'server',
  'utils',
  'processDocInfos.js'
);

try {
  let content = fs.readFileSync(filePath, 'utf8');
  const original = `throw new Error(\`The route must start with the baseUrl "\${baseUrl}", but was "\${url}". This is a bug, please report it.\`);`;
  const patched = `return;`;

  if (content.includes(original)) {
    content = content.replace(original, patched);
    fs.writeFileSync(filePath, content, 'utf8');
    console.log('✅ Patched @easyops-cn/docusaurus-search-local for i18n compatibility');
  } else if (content.includes(patched)) {
    console.log('ℹ️  @easyops-cn/docusaurus-search-local already patched');
  } else {
    console.warn('⚠️  Could not find expected code to patch in processDocInfos.js');
  }
} catch (err) {
  console.warn('⚠️  Could not patch @easyops-cn/docusaurus-search-local:', err.message);
}
